import numpy as np

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x, lb, ub):
        return np.clip(x, lb, ub)

    x_best = np.zeros(dim)
    f_best = float('inf')

    for _ in range(budget):
        x_candidate = clip(rng.uniform(lb, ub, size=dim), lb, ub)
        f_candidate = func(x_candidate)

        if f_candidate < f_best:
            f_best = f_candidate
            x_best = x_candidate

    return x_best
